/**
 * UUID v4 generator backed by Node.js built-in crypto.
 *
 * Uses `crypto.randomUUID()` which is FIPS-compliant and available since
 * Node.js 14.17.0 / 15.6.0 — no external dependencies required.
 */
import { randomUUID } from "node:crypto";

/**
 * Generate a cryptographically-secure UUID v4 string.
 * @returns {string}
 */
export function generateUUID() {
  return randomUUID();
}
